 stop=next(i for i,n in enumerate(tree.body) if i>start and isinstance(n,ast.Assign) and isinstance(n.targets[0],ast.Name) and n.targets[0].id=='args')
 return compile(ast.Module(body=tree.body[start:stop+1],type_ignores=[]),'actual-selected-parser','exec')
